import sys


def deal(a, R, C, H, V):
    cutR=[]
    cutC=[]
    sumR=[]
    sumC=[]
    tt = 0
    pc = 0
    for r in range(R):
        z = sum(a[r])
        sumR.append(z)
        tt = tt+z
    for c in range(C):
        z = 0
        for r in range(R):
            z = z+a[r][c]
        sumC.append(z)
    pc = tt / (H + 1)
    pc = pc / (V+1)
    if pc * (H+1) * (V+1) < tt:
        return -1

    k = -1
    for h in range(H):
        z = -1
        while (z < pc*(V+1)):
            if (z < 0):
                z = 0
            k = k+1
            if k >= R:
                return -1
            z = z+sumR[k]
            if z == pc*(V+1):
                cutR.append(k)
                break
            elif z > pc*(V+1):
                return -1

    k = -1
    for v in range(V):
        z = -1
        while (z < pc*(H+1)):
            if (z < 0):
                z = 0
            k = k+1
            if k >= C:
                return -1
            z = z + sumC[k]
            if z == pc * (H + 1):
                cutC.append(k)
                break
            elif z > pc * (H + 1):
                return -1

    for i in range(H+1):
        for j in range(V+1):
            if i == 0:
                u = 0
            else:
                u = cutR[i-1]+1
            if i == H:
                uu = R
            else:
                uu = cutR[i]+1

            if j == 0:
                l = 0
            else:
                l = cutC[j-1]+1
            if j == V:
                ll = C
            else:
                ll = cutC[j]+1

            z = 0
            for r in range(u,uu):
                for c in range(l, ll):
                    z = z+int(a[r][c])
            if z != pc:
                return -1
    return 1



