    jb = new JButton(getMessage("btn_close"));
    jb.addActionListener(new ActionListener() {

        public void actionPerformed(ActionEvent e) {
            jd.dispose();
        }
    });
    jp.add(jb);
    jd.add(jp);
    jd.pack();
    setCentral(jd);
}

