    public static void main(String[] args)
    {
        Scanner sc = new Scanner(System.in);
        int test = 1, cases = Integer.parseInt(sc.nextLine());

        ArrayList<Integer> mushrooms = new ArrayList<Integer>();

        int times;
        int last;
        int curr;

        int minEaten, minRate, rateEaten;

        int i;

        while(test <= cases)
        {
            mushrooms.clear();

            times = sc.nextInt();

