    skip_bits(&conf->gb, 1);



    /* get matrix */

    if (get_bits1(&conf->gb)) {

        for(i=0;i<64;i++) {

            v = get_bits(&conf->gb, 8);

            j = conf->intra_scantable.permutated[i];

            conf->intra_matrix[j] = v;

            conf->chroma_intra_matrix[j] = v;

        }

#ifdef DEBUG

        dprintf("intra matrix present
");

        for(i=0;i<64;i++)

            dprintf(" %d", conf->intra_matrix[conf->intra_scantable.permutated[i]]);

        printf("
");

#endif

    } else {

        for(i=0;i<64;i++) {

            int j= conf->idct_permutation[i];

            v = ff_mpeg1_default_intra_matrix[i];

            conf->intra_matrix[j] = v;

            conf->chroma_intra_matrix[j] = v;

        }

    }

    if (get_bits1(&conf->gb)) {

        for(i=0;i<64;i++) {

            v = get_bits(&conf->gb, 8);

            j = conf->intra_scantable.permutated[i];

            conf->inter_matrix[j] = v;

            conf->chroma_inter_matrix[j] = v;

        }

#ifdef DEBUG

        dprintf("non intra matrix present
");

        for(i=0;i<64;i++)

            dprintf(" %d", conf->inter_matrix[conf->intra_scantable.permutated[i]]);

        printf("
");

#endif

    } else {

        for(i=0;i<64;i++) {

            int j= conf->idct_permutation[i];

            v = ff_mpeg1_default_non_intra_matrix[i];

            conf->inter_matrix[j] = v;

            conf->chroma_inter_matrix[j] = v;

        }

    }



    /* we set mpeg2 parameters so that it emulates mpeg1 */

    conf->progressive_sequence = 1;

    conf->progressive_frame = 1;

    conf->picture_structure = PICT_FRAME;

    conf->frame_pred_frame_dct = 1;

    conf->mpeg2 = 0;

    AVcms->sub_id = 1; /* indicates mpeg1 */

    return 0;

}

