import sys;
import os;

def read(): return sys.stdin.readline().strip();
def pflush(x): print x; sys.stdout.flush();

hasWritten = False;
def log(x):
    global hasWritten;
    try:
        if hasWritten == False: os.remove("log.txt");
    except: pass;
    hasWritten = True;
    with open("log.txt", "a") as f: f.write("%s\n"%x);

def solve():
    N = int(read());
    P = map(int, read().split());

    letters = "ABCDEFGHIJKLMNOPQRSTUVWXYZ";
    output = [];
    while sum(P) > 0:
        _,i1 = max( (v, i) for i,v in enumerate(P) );
        P[i1] -= 1;

        if all( 2*v <= sum(P) for v in P ):
            output.append(letters[i1]);
            continue;

        _,i2 = max( (v, i) for i,v in enumerate(P) );
        P[i2] -= 1;

        output.append("%s%s"%(letters[i1], letters[i2]));

    return " ".join(output);

T = int(read());
for ind in xrange(T): print "Case #%s: %s"%(ind+1, solve());

